PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE ins_rows (
  phase       TEXT    NOT NULL,   -- beta＝開服前，live＝開服後（之後可以加新的階段）
  realm       TEXT    NOT NULL,
  faction     TEXT    NOT NULL CHECK (faction IN ('Alliance', 'Horde')),
  kind        TEXT    NOT NULL CHECK (kind IN ('c', 'g', 'b', 'r')),
  k           TEXT    NOT NULL,
  data        TEXT    NOT NULL,
  updated_at  INTEGER NOT NULL,
  PRIMARY KEY (phase, kind, realm, faction, k)
) WITHOUT ROWID;
